		StringBuilder msg = new StringBuilder( "-- Failed to get all TrainingRun : " );        
		List<TrainingRun> collection  = new ArrayList<>();

		try {
			// call the static get method on the TrainingRunService
			collection = TrainingRunService.getTrainingRunInstance().getAllTrainingRun();
			assertNotNull( collection, "An Empty collection of TrainingRun was incorrectly returned.");
			
			// Now print out the values
			TrainingRun entity = null;            
			Iterator<TrainingRun> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getTrainingRunId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
